/**
 * production-tooltip.tsx
 * Solid-based tooltips for production chooser entries.
 */
import { createMemo, For, Match, ParentComponent, Show, splitProps, Switch, type Component, type JSX } from "solid-js";

import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import {
	Tooltip,
	TooltipBaseProps,
	TooltipHorizontalPosition,
	TooltipVerticalPosition,
} from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { GetTownFocusBlp, ProductionPanelCategory } from "#base/ui/production-chooser/production-chooser-helpers.js";
import type { AdvisorRecommendations } from "#base/ui/tutorial/advisor-utilities.js";
import { ConstructibleDetails } from "#base/ui-next/components/constructible-details.jsx";
import { AdvisorRecommendationPill, PillText } from "#base/ui-next/components/pills.jsx";

const BULLET_CHAR = String.fromCodePoint(0x2022);

type MaybeString = string | null | undefined;

const normalizeCategory = (value?: string | ProductionPanelCategory | null): ProductionPanelCategory => {
	if (!value) {
		return ProductionPanelCategory.BUILDINGS;
	}
	switch (value) {
		case ProductionPanelCategory.UNITS:
			return ProductionPanelCategory.UNITS;
		case ProductionPanelCategory.PROJECTS:
			return ProductionPanelCategory.PROJECTS;
		case ProductionPanelCategory.WONDERS:
			return ProductionPanelCategory.WONDERS;
		default:
			return ProductionPanelCategory.BUILDINGS;
	}
};

const parseRecommendations = (values?: AdvisorRecommendations[]): AdvisorRecommendations[] => values ?? [];

interface ProductionTooltipProps extends Omit<TooltipBaseProps, "initialVPosition" | "initialHPosition" | "offset"> {
	initialVPosition?: TooltipVerticalPosition;
	initialHPosition?: TooltipHorizontalPosition;
	offset?: number;
	category?: ProductionPanelCategory | string | null;
	type?: MaybeString;
	name?: MaybeString;
	description?: MaybeString;
	tooltipDescription?: MaybeString;
	recommendations?: AdvisorRecommendations[];
	isPurchase?: boolean;
	cost?: string;
	warehouseCount?: MaybeString;
	highestAdjacency?: MaybeString;
	canGetWarehouseBonuses?: boolean;
	canGetAdjacencyBonuses?: boolean;
	projectGrowthType?: MaybeString;
}

interface ConstructibleTooltipProps extends JSX.HTMLAttributes<HTMLDivElement> {
	constructibleType?: MaybeString;
	name?: MaybeString;
	description?: MaybeString;
	recommendations: AdvisorRecommendations[];
	warehouseCount?: MaybeString;
	canGetWarehouseBonuses?: boolean;
	highestAdjacency?: MaybeString;
	canGetAdjacencyBonuses?: boolean;
	isPurchase?: boolean;
	productionCost?: number;
}

interface UnitTooltipProps extends JSX.HTMLAttributes<HTMLDivElement> {
	unitType?: MaybeString;
	name?: MaybeString;
	description?: MaybeString;
	recommendations: AdvisorRecommendations[];
	isPurchase?: boolean;
	cost?: string;
}

interface ProjectTooltipProps extends JSX.HTMLAttributes<HTMLDivElement> {
	projectType?: MaybeString;
	name?: MaybeString;
	description?: MaybeString;
	recommendations: AdvisorRecommendations[];
	growthType?: MaybeString;
	cost?: string;
	isPurchase?: boolean;
}

const ProductionConstructibleTooltipContent: Component<ConstructibleTooltipProps> = (props) => {
	const [local, other] = splitProps(props, [
		"constructibleType",
		"name",
		"description",
		"recommendations",
		"warehouseCount",
		"canGetWarehouseBonuses",
		"highestAdjacency",
		"canGetAdjacencyBonuses",
		"isPurchase",
		"productionCost",
		"class",
	]);
	const definition = createMemo(() => {
		const definition = local.constructibleType ? GameInfo.Constructibles.lookup(local.constructibleType) : null;
		if (!definition) {
			console.error(`No constructible definition found for type: ${local.constructibleType}`);
		}
		return definition;
	});
	const title = createMemo(() => definition()?.Name ?? local.name ?? "");
	const showWarehouse = () => local.canGetWarehouseBonuses && !!local.warehouseCount;
	const showAdjacency = () => local.canGetAdjacencyBonuses && !!local.highestAdjacency;
	const showCostPill = () => local.productionCost !== undefined;
	const showBottomRow = () => local.recommendations.length > 0 || showCostPill();

	return (
		<div
			class={`flex flex-col font-body text-sm text-accent-2 ${local.class ?? ""}`}
			{...other}
		>
			<FiligreeTitle.Small
				class="mb-1"
				text={title()}
				bgGlow
			/>
			<Show when={definition()}>
				{(definition) => (
					<ConstructibleDetails
						class="mb-1"
						definition={definition()}
						isPurchase={local.isPurchase}
						warehouseBonus={showWarehouse() ? (local.warehouseCount ?? "0") : undefined}
						adjacencyBonus={showAdjacency() ? (local.highestAdjacency ?? "0") : undefined}
					/>
				)}
			</Show>
			<Show when={showBottomRow()}>
				<div class="flex flex-row flex-wrap items-center justify-center mt-2 -mb-1">
					<For each={local.recommendations}>
						{(rec, index) => (
							<AdvisorRecommendationPill
								textOverride="LOC_UI_RECOMMENDATION_DEFAULT"
								class={index() > 0 ? "ml-2 mt-2" : "mt-2"}
								recommendation={rec}
							/>
						)}
					</For>
					<Show when={showCostPill()}>
						<PillText
							class={local.recommendations.length > 0 ? "ml-2 mt-2" : "mt-2"}
							text="LOC_CARD_COST"
							args={[
								`${local.productionCost}[icon:${local.isPurchase ? "YIELD_GOLD" : "YIELD_PRODUCTION"}]`,
							]}
						/>
					</Show>
				</div>
			</Show>
		</div>
	);
};

const ProductionUnitTooltipContent: Component<UnitTooltipProps> = (props) => {
	const [local, other] = splitProps(props, [
		"unitType",
		"name",
		"description",
		"recommendations",
		"isPurchase",
		"cost",
		"class",
	]);
	const definition = createMemo(() => (local.unitType ? GameInfo.Units.lookup(local.unitType) : null));
	const title = createMemo(() => definition()?.Name ?? local.name ?? "");
	const descriptionKey = createMemo(() => local.description ?? definition()?.Description ?? "");
	const maintenanceValue = createMemo(() => definition()?.Maintenance ?? 0);
	const maintenanceVisible = () => maintenanceValue() > 0;
	const productionCost = createMemo(() => {
		if (local.isPurchase) {
			return local.cost ? Number(local.cost) : undefined;
		}
		if (!definition()) {
			return undefined;
		}
		const cityID = UI.Player.getHeadSelectedCity();
		if (!cityID) {
			return undefined;
		}
		const city = Cities.get(cityID);
		return city?.Production?.getUnitProductionCost(definition()!.UnitType);
	});
	const showCostPill = () => productionCost() !== undefined;
	const showBottomRow = () => local.recommendations.length > 0 || showCostPill();

	return (
		<div
			class={`flex flex-col font-body text-sm text-accent-2 ${local.class ?? ""}`}
			{...other}
		>
			<FiligreeTitle.Small
				class="mb-1"
				text={title()}
				bgGlow
			/>
			<div class="img-base-ticket-bg-container">
				<div class="img-shell-line-divider h-1 w-1/2 self-center mb-2" />
				<Show when={descriptionKey()}>
					<L10n.Stylize
						class="mb-2"
						text={descriptionKey() ?? ""}
					/>
				</Show>
				<div class="img-shell-line-divider h-1 w-1/2 self-center mb-2" />
				<Show when={maintenanceVisible()}>
					<div class="flex items-center">
						<L10n.Stylize
							class="mr-2"
							text="LOC_UI_PRODUCTION_MAINTENANCE"
						/>
						<Icon
							class="size-5 mr-1"
							name="YIELD_GOLD"
							aria-label={Locale.compose("LOC_YIELD_GOLD")}
						/>
						<div class="text-negative-light">{`-${maintenanceValue()}`}</div>
					</div>
				</Show>
			</div>
			<Show when={showBottomRow()}>
				<div class="flex flex-row flex-wrap items-center justify-center mt-2 -mb-1">
					<For each={local.recommendations}>
						{(rec, index) => (
							<AdvisorRecommendationPill
								textOverride="LOC_UI_RECOMMENDATION_DEFAULT"
								class={index() > 0 ? "ml-2 mt-2" : "mt-2"}
								classList={{
									"ml-2": index() > 0,
								}}
								recommendation={rec}
							/>
						)}
					</For>
					<Show when={showCostPill()}>
						<PillText
							class={local.recommendations.length > 0 ? "ml-2 mt-2" : "mt-2"}
							text="LOC_CARD_COST"
							args={[`${productionCost()}[icon:${local.isPurchase ? "YIELD_GOLD" : "YIELD_PRODUCTION"}]`]}
						/>
					</Show>
				</div>
			</Show>
		</div>
	);
};

const parseProjectTypeHash = (value?: MaybeString): number | undefined => {
	if (!value) {
		return undefined;
	}
	const numeric = Number(value);
	if (!Number.isNaN(numeric)) {
		return numeric;
	}
	return Game.getHash(value);
};

interface ProjectRequirementsData {
	/** The localization key for the requirement text. */
	key: string;
	/** The arguments for the localization string. */
	args: LocalizedTextArgument[];
}

const getProjectRequirements = (projectHash?: number): ProjectRequirementsData | undefined => {
	if (!projectHash) {
		return undefined;
	}
	const project = GameInfo.Projects.lookup(projectHash);
	if (!project) {
		return undefined;
	}
	if (project.PrereqPopulation > 0) {
		return { key: "LOC_UI_PRODUCTION_REQUIRES_POPULATION", args: [project.PrereqPopulation] };
	}
	if (project.PrereqConstructible) {
		const definition = GameInfo.Constructibles.lookup(project.PrereqConstructible);
		if (definition) {
			return { key: "LOC_UI_PRODUCTION_REQUIRES_CONSTRUCTIBLE", args: [definition.Name ?? ""] };
		}
	}
	return undefined;
};

const ProductionProjectTooltipContent: Component<ProjectTooltipProps> = (props) => {
	const [local, other] = splitProps(props, [
		"projectType",
		"name",
		"description",
		"recommendations",
		"growthType",
		"class",
	]);
	const projectHash = createMemo(() => parseProjectTypeHash(local.projectType));
	const iconUrl = createMemo(() => GetTownFocusBlp(local.growthType ?? null, projectHash() ?? null));
	const iconBackground = createMemo(() => (iconUrl() ? `url(${iconUrl()})` : undefined));
	const productionCost = createMemo(() => {
		const hash = projectHash();
		if (!hash) {
			return undefined;
		}
		const cityID = UI.Player.getHeadSelectedCity();
		if (!cityID) {
			return undefined;
		}
		const city = Cities.get(cityID);
		return city?.Production?.getProjectProductionCost(hash);
	});
	const definition = createMemo(() => GameInfo.Projects.lookup(projectHash() ?? ""));
	const requirementsText = createMemo(() => getProjectRequirements(projectHash()));
	/** Applies spacing rules for bulleted list content in project descriptions. */
	const applyDescriptionFormatting = (element: HTMLDivElement | undefined) => {
		if (!element) {
			return;
		}
		let firstChild = true;
		let prevChildIsList = false;
		for (const node of Array.from(element.children)) {
			const isList = node.innerHTML.includes(BULLET_CHAR);
			if (isList) {
				node.classList.add("ml-4");
			}
			if (!firstChild && (!prevChildIsList || !isList)) {
				node.classList.add("mt-2");
			}
			firstChild = false;
			prevChildIsList = isList;
		}
	};
	const showCostPill = () => productionCost() !== undefined;
	const showBottomRow = () => local.recommendations.length > 0 || showCostPill();

	return (
		<div
			class={`flex flex-col text-accent-2 font-body text-sm relative ${local.class ?? ""}`}
			{...other}
		>
			<FiligreeTitle.None
				text={local.name ?? ""}
				bgGlow
			/>
			<div class="flex flex-row items-center self-center">
				<div class="filigree-shell-small-left" />
				<Icon
					class="size-12"
					name={iconBackground() ?? ""}
					isUrl={true}
				/>
				<div class="filigree-shell-small-right" />
			</div>
			<Show when={local.description || definition()?.Description}>
				{(text) => (
					<div class="img-base-ticket-bg-container">
						<L10n.Stylize
							class="mt-2"
							text={text() ?? ""}
							ref={applyDescriptionFormatting}
						/>
					</div>
				)}
			</Show>
			<Show when={requirementsText()}>
				{(reqData) => (
					<L10n.Stylize
						class="flex mt-2 p-2"
						style={{ "background-color": "rgb(0 0 0 / 0.2)" }}
						text={reqData().key}
						args={reqData().args}
					/>
				)}
			</Show>
			<Show when={showBottomRow()}>
				<div class="flex flex-row flex-wrap items-center justify-center mt-4 -mb-1">
					<For each={local.recommendations}>
						{(rec, index) => (
							<AdvisorRecommendationPill
								textOverride="LOC_UI_RECOMMENDATION_DEFAULT"
								class={index() > 0 ? "ml-2 mt-2" : "mt-2"}
								recommendation={rec}
							/>
						)}
					</For>
					<Show when={showCostPill()}>
						<PillText
							class={local.recommendations.length > 0 ? "ml-2 mt-2" : "mt-2"}
							text="LOC_CARD_COST"
							args={[`${productionCost()}[icon:YIELD_PRODUCTION]`]}
						/>
					</Show>
				</div>
			</Show>
		</div>
	);
};

export const ProductionTooltipComponent: ParentComponent<ProductionTooltipProps> = (props) => {
	const [local, other] = splitProps(props, [
		"category",
		"children",
		"class",
		"type",
		"name",
		"description",
		"tooltipDescription",
		"recommendations",
		"isPurchase",
		"cost",
		"warehouseCount",
		"highestAdjacency",
		"canGetWarehouseBonuses",
		"canGetAdjacencyBonuses",
		"projectGrowthType",
	]);

	const normalizedCategoryValue = createMemo(() => normalizeCategory(local.category));
	const recommendations = createMemo(() => parseRecommendations(local.recommendations));
	const constructibleProductionCost = createMemo(() => {
		if (local.isPurchase) {
			return local.cost ? Number(local.cost) : undefined;
		}
		if (!local.type) {
			return undefined;
		}
		const cityID = UI.Player.getHeadSelectedCity();
		if (!cityID) {
			return undefined;
		}
		const city = Cities.get(cityID);
		return city?.Production?.getConstructibleProductionCost(Game.getHash(local.type));
	});
	const tooltipContentClass = () => `w-128`;
	return (
		<Tooltip {...other}>
			<Tooltip.Trigger>{local.children}</Tooltip.Trigger>
			<Tooltip.Content class={local.class}>
				<Tooltip.Frame>
					<Switch
						fallback={
							<ProductionConstructibleTooltipContent
								class={tooltipContentClass()}
								constructibleType={local.type}
								name={local.name}
								description={local.description}
								recommendations={recommendations()}
								warehouseCount={local.warehouseCount}
								canGetWarehouseBonuses={local.canGetWarehouseBonuses}
								highestAdjacency={local.highestAdjacency}
								canGetAdjacencyBonuses={local.canGetAdjacencyBonuses}
								isPurchase={local.isPurchase}
								productionCost={constructibleProductionCost()}
							/>
						}
					>
						<Match when={normalizedCategoryValue() === ProductionPanelCategory.UNITS}>
							<ProductionUnitTooltipContent
								class={tooltipContentClass()}
								unitType={local.type}
								name={local.name}
								description={local.description}
								recommendations={recommendations()}
								isPurchase={local.isPurchase}
								cost={local.cost}
							/>
						</Match>
						<Match when={normalizedCategoryValue() === ProductionPanelCategory.PROJECTS}>
							<ProductionProjectTooltipContent
								class={tooltipContentClass()}
								projectType={local.type}
								name={local.name}
								description={local.tooltipDescription ?? local.description}
								recommendations={recommendations()}
								growthType={local.projectGrowthType}
							/>
						</Match>
					</Switch>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const ProductionTooltip = ComponentRegistry.register({
	name: "ProductionTooltip",
	createInstance: ProductionTooltipComponent,
	images: ["blp:base_ticket-bg", "blp:shell_line-divider"],
});
